85	  let seq = 0; // seq of the last effective message
86	  let bytes = 0;
87	  let published = 0;
88	  let replayed = 0;
89	  // dedupKey -> { id, seq } for effective messages
90	  const dedup = new Map();
91	  // dedupKey -> { promise, resolve, reject } for first publish in flight
92	  const pending = new Map();
93	  // consumer name -> position (seq of the last consumed message; 0 = none)
94	  const positions = new Map();
95	  // generation of the newest durable snapshot; 0 = no snapshot yet
96	  let snapshotGen = 0;
97	  // messages folded into the snapshot, served to replay/read after truncation
98	  let baseMessages = [];
99	
100	  // ---- synchronous recovery so stats() is correct the moment createBus returns
101	  mkdirSync(dir, { recursive: true });
102	
103	  // A leftover tmp file is a snapshot that crashed mid-write. The pre-compact
104	  // log is still intact, so the half snapshot carries no state: drop it.
105	  rmSync(snapshotTmpPath, { force: true });
106	
107	  if (existsSync(snapshotPath)) {
108	    const snap = JSON.parse(readFileSync(snapshotPath, 'utf8'));
109	    snapshotGen = snap.gen;
110	    seq = snap.seq;
111	    bytes = snap.bytes;
112	    published = snap.published;
113	    replayed = snap.replayed;
114	    for (const [key, value] of snap.dedup) dedup.set(key, value);
