121	      seq = entry.seq;
122	      bytes += entry.bytes;
123	      published += 1;
124	      if (typeof entry.d === 'string') {
125	        dedup.set(entry.d, { id: entry.id, seq: entry.seq });
126	      }
127	    } else if (entry.t === 's') {
128	      replayed += entry.n;
129	    } else if (entry.t === 'p') {
130	      positions.set(entry.name, entry.pos);
131	    }
132	  };
