134	  const markerLine = (gen) => JSON.stringify({ t: 'c', gen }) + '\n';
135	
136	  if (existsSync(logPath)) {
137	    const raw = readFileSync(logPath);
138	    const { entries, durable } = parseLog(raw);
139	    // Bytes past the final newline are a torn (partially durable) trailing
140	    // write. Drop them: that publish was never acknowledged, so upstream
141	    // resends it.
142	    if (durable < raw.length) {
143	      truncateSync(logPath, durable);
144	    }
145	    if (snapshotGen > 0) {
146	      const first = entries[0];
