148	        // Live post-compact log: only entries after the marker are new.
149	        for (const entry of entries.slice(1)) applyEntry(entry);
150	      } else {
151	        // Crash between snapshot rename and log truncation (or between
152	        // truncation and marker write): every byte of this log is already
153	        // folded into the snapshot. Reset it to just the marker so the
