169	  let closed = false;
170	  // A failed append may leave a torn line; stop appending so later writes
171	  // cannot glue themselves onto it. The torn tail is truncated on reopen.
172	  let broken = false;
173	
174	  // All disk mutation by publish/replay/compact happens inside this serial
175	  // chain; writeSync keeps each append atomic with respect to the event loop
