236	    publish(record) {
237	      if (closed) {
238	        return Promise.reject(new Error('bus is closed'));
239	      }
240	      if (record === null || typeof record !== 'object' || Array.isArray(record)) {
241	        return Promise.reject(new TypeError('publish: record must be a JSON object'));
242	      }
243	      const dedupKey = record.dedupKey;
244	      if (dedupKey !== undefined && typeof dedupKey !== 'string') {
245	        return Promise.reject(new TypeError('publish: dedupKey must be a string'));
246	      }
247	      try {
248	        assertJsonSafe(record);
249	      } catch (err) {
250	        return Promise.reject(err);
251	      }
252	      const size = Buffer.byteLength(JSON.stringify(record), 'utf8');
253	
254	      // Duplicate of an effective message (possibly recovered from disk).
255	      if (dedupKey !== undefined) {
256	        const first = dedup.get(dedupKey);
257	        if (first) {
258	          return Promise.resolve({ id: first.id, seq: first.seq });
259	        }
260	        const inflight = pending.get(dedupKey);
261	        if (inflight) {
262	          return inflight.promise;
263	        }
264	      }
265	
266	      // Reserve in-flight dedup at call time so concurrent resends of the
267	      // same order share the first result; FIFO enqueue assigns seq in
268	      // invocation order.
269	      let resolveResult;
270	      let rejectResult;
271	      const promise = new Promise((resolve, reject) => {
272	        resolveResult = resolve;
273	        rejectResult = reject;
274	      });
275	      if (dedupKey !== undefined) {
276	        pending.set(dedupKey, { promise, resolve: resolveResult, reject: rejectResult });
277	      }
278	
279	      enqueue(() => {
280	        if (closed || broken) {
281	          throw new Error('bus is closed');
282	        }
283	        const mySeq = seq + 1;
284	        const id = randomUUID();
285	        const entry = { t: 'm', seq: mySeq, id, bytes: size, record };
286	        if (dedupKey !== undefined) entry.d = dedupKey;
287	        try {
288	          // Durable before acknowledgement: state changes only after the
289	          // write (and optional fsync) succeeds.
290	          writeLine(entry);
291	        } catch (err) {
292	          broken = true;
293	          throw err;
294	        }
295	        seq = mySeq;
296	        bytes += size;
297	        published += 1;
