299	          dedup.set(dedupKey, { id, seq: mySeq });
300	          pending.delete(dedupKey);
301	          resolveResult({ id, seq: mySeq });
302	        }
303	        return { id, seq: mySeq };
304	      }).then(
305	        (ack) => {
306	          if (dedupKey === undefined) resolveResult(ack);
307	        },
308	        (err) => {
309	          if (dedupKey !== undefined) pending.delete(dedupKey);
310	          rejectResult(err);
311	        },
312	      );
313	
314	      return promise;
315	    },
316	
317	    replay(from = 0) {
318	      if (closed) {
319	        return Promise.reject(new Error('bus is closed'));
320	      }
321	      if (typeof from !== 'number' || !Number.isInteger(from) || from < 0) {
322	        return Promise.reject(new RangeError('replay: from must be a non-negative integer'));
323	      }
324	
325	      return enqueue(() => {
326	        if (closed || broken) {
327	          throw new Error('bus is closed');
328	        }
329	        // replay(from) is inclusive of from; messagesAfter takes an
330	        // exclusive lower bound.
331	        const out = messagesAfter(from - 1);
332	        const n = out.length;
333	        if (n > 0) {
334	          try {
335	            writeLine({ t: 's', n });
336	          } catch (err) {
337	            broken = true;
338	            throw err;
339	          }
340	          replayed += n;
341	        }
342	        return out;
343	      });
344	    },
345	
346	    register(name) {
347	      assertOpen();
348	      assertName(name);
349	      const current = positions.get(name);
350	      // Re-registering an existing name must not reset its position.
351	      if (current !== undefined) {
352	        return current;
353	      }
354	      persistPosition(name, 0);
355	      positions.set(name, 0);
356	      return 0;
357	    },
358	
359	    advance(name, to) {
360	      assertOpen();
361	      assertName(name);
362	      if (typeof to !== 'number' || !Number.isInteger(to) || to < 0) {
363	        throw new RangeError('advance: position must be a non-negative integer');
364	      }
365	      const current = positions.get(name);
366	      if (current !== undefined) {
367	        if (to < current) {
368	          throw new RangeError('advance: position cannot move backwards');
369	        }
370	        if (to === current) {
371	          return current;
372	        }
373	      }
374	      // An unknown name is auto-registered, same as register() first.
375	      persistPosition(name, to);
376	      positions.set(name, to);
377	      return to;
378	    },
379	
380	    read(name) {
381	      assertOpen();
382	      assertName(name);
383	      let pos = positions.get(name);
384	      if (pos === undefined) {
385	        pos = 0;
386	        persistPosition(name, pos);
387	        positions.set(name, pos);
388	      }
389	      // read never moves the position; advance() is how consumption lands.
390	      return messagesAfter(pos);
391	    },
392	
393	    compact() {
394	      if (closed) {
395	        return Promise.reject(new Error('bus is closed'));
396	      }
397	      return enqueue(() => {
398	        if (closed || broken) {
399	          throw new Error('bus is closed');
400	        }
401	        const { entries } = parseLog(readFileSync(logPath));
402	        const messages = baseMessages.slice();
403	        for (const entry of entries) {
404	          if (entry.t === 'm') {
405	            messages.push({ seq: entry.seq, id: entry.id, record: entry.record });
406	          }
407	        }
408	        const gen = snapshotGen + 1;
409	        const snapshot = {
410	          v: 1,
411	          gen,
412	          seq,
413	          bytes,
414	          published,
415	          replayed,
416	          positions: Object.fromEntries(positions),
417	          dedup: Array.from(dedup.entries()),
418	          messages,
419	        };
420	        // The snapshot is durable (fsync + atomic rename) before the log is
421	        // truncated, so a crash anywhere leaves either the intact old log
422	        // (half tmp snapshot, discarded on reopen) or the new marker-led
423	        // log — never something in between.
424	        const tmpFd = openSync(snapshotTmpPath, 'w');
425	        try {
426	          writeSync(tmpFd, Buffer.from(JSON.stringify(snapshot) + '\n', 'utf8'));
427	          fsyncSync(tmpFd);
428	        } finally {
429	          closeSync(tmpFd);
430	        }
431	        renameSync(snapshotTmpPath, snapshotPath);
432	        try {
433	          ftruncateSync(fd, 0);
434	          writeSync(fd, Buffer.from(markerLine(gen), 'utf8'));
435	          fsyncSync(fd);
436	        } catch (err) {
437	          // If the marker did not land, later appends would sit in a log the
438	          // recovery path would discard as pre-snapshot. Stop the bus instead.
439	          broken = true;
440	          throw err;
441	        }
442	        snapshotGen = gen;
443	        baseMessages = messages;
444	      });
445	    },
446	
447	    stats() {
448	      return { seq, bytes, published, replayed };
449	    },
450	
451	    close() {
452	      if (closed) {
453	        return Promise.resolve();
454	      }
455	      closed = true;
456	      // Reject any publish whose dedup reservation is still queued.
457	      for (const [key, p] of pending) {
458	        p.reject(new Error('bus is closed'));
459	        pending.delete(key);
460	      }
461	      return enqueue(() => {
462	        try {
463	          if (fsync) fsyncSync(fd);
464	        } finally {
465	          closeSync(fd);
466	        }
467	      });
468	    },
469	  };
470	
471	  return bus;
472	}
